return {
  heal: {
    hook: "onEvent",
    eventType: "entityAttack",
    promptOnPlayer: async (H, actor, ctx) => {
      if (!ctx.payload.targetActorIds.includes(actor.id) || !H.condition.has(actor, "ready")) return false;
      if (!(await H.ask.confirm({
        title: "Masochist",
        bodyHtml: "Expend <strong>Ready</strong> to heal <strong>1 Wound</strong>?",
        yesLabel: "Expend Ready",
        noLabel: "Skip",
      }))) return false;
      await H.condition.set(actor, "ready", false);
      await H.resource.adjust(actor, { wounds: 1 });
      await H.chat.post(`${actor.name} heals 1 Wound (Masochist).`, actor);
      return true;
    },
  },
};
